select count(1) from repair_order
where del_flag = '0' and elevator_id = #{elevatorId}
  and order_status in ('pending','assigned','accepted','arrived','repairing','repaired','appealed')

select count(1) from repair_order
where del_flag = '0'

    and order_status = #{orderStatus}

select avg(timestampdiff(minute, o.report_time, o.assign_time))
from repair_order o
left join elevator e on o.elevator_id = e.elevator_id
left join building b on e.building_id = b.building_id
where o.del_flag = '0' and o.assign_time is not null
and b.community_id = #{communityId}
and o.report_time >= #{beginTime}
and o.report_time <= #{endTime}

select avg(timestampdiff(minute, o.arrive_time, o.finish_time))
from repair_order o
left join elevator e on o.elevator_id = e.elevator_id
left join building b on e.building_id = b.building_id
where o.del_flag = '0' and o.arrive_time is not null and o.finish_time is not null
and b.community_id = #{communityId}
and o.report_time >= #{beginTime}
and o.report_time <= #{endTime}

